import {awardCost,compareMiles,calculateEarn,rollingTotals,promotionProgress,renewalProgress,expiringRecords,targetProgress,number,parseDate,addDays} from './lib/miles.js';
const $=s=>document.querySelector(s);
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const today=()=>new Intl.DateTimeFormat('sv-SE',{timeZone:'Europe/Istanbul',year:'numeric',month:'2-digit',day:'2-digit'}).format(new Date());
const defaults={lang:'tr',balance:45000,example:true,cabin:'economy',awardType:'promo',search:'',affordable:false,compare:{cashPrice:12000,awardCash:2000,miles:20000,currency:'TRY',example:true},earn:{bookingClass:'K',tier:'elite',routeType:'international',distance:6855,ticketType:'paid',example:true},status:{tier:'classic',residence:'Turkey',target:'classicPlus',asOf:today(),forecast:addDays(today(),90),start:'',firstEnd:'',end:''},goal:{region:'avrupa-2',cabin:'business',type:'promo',passengers:2,directions:2},records:[]};
let s=structuredClone(defaults),page='explore',data={},earned=null,earnDirty=false,timer;
const STORE='mil-pusulasi-v1';
try{const stored=JSON.parse(localStorage.getItem(STORE)||'null');if(stored){s={...defaults,...stored,compare:{...defaults.compare,...stored.compare},earn:{...defaults.earn,...stored.earn},status:{...defaults.status,...stored.status},goal:{...defaults.goal,...stored.goal}};number(s.balance,{integer:true});if(!['tr','en'].includes(s.lang)||!['economy','business'].includes(s.cabin)||!['promo','standard'].includes(s.awardType))throw Error('storage');s.records=(Array.isArray(stored.records)?stored.records:[]).filter(r=>{try{parseDate(r.date);number(r.statusMiles,{integer:true});number(r.flights,{integer:true,max:1000});return typeof r.label==='string'&&typeof r.id==='string'&&['credited','planned'].includes(r.state);}catch{return false;}});}}catch{s=structuredClone(defaults);}
const T=(tr,en)=>s.lang==='en'?en:tr;
const words={mil:['mil','miles'],status:['Statü Mili','Status Miles'],cabin:['Kabin','Cabin'],type:['Ödül bilet türü','Award type'],promo:['Promosyon ödül','Promotional award'],standard:['Ödül bilet','Award ticket'],balance:['Kullanılabilir mil bakiyem','My available miles'],compare:['Karşılaştır','Compare'],target:['Yolculuk hedefi yap','Set trip goal'],credited:['Hesabıma işlenmiş','Credited'],planned:['Planlanan','Planned'],date:['Tarih','Date'],record:['Kayıt','Record'],delete:['Sil','Delete'],sources:['Veri kaynakları','Data sources'],calculate:['Hesapla','Calculate'],close:['Kapat','Close']};
const W=k=>T(...words[k]);
const loc=()=>s.lang==='tr'?'tr-TR':'en-GB';
const F=(n,d=0)=>new Intl.NumberFormat(loc(),{minimumFractionDigits:d,maximumFractionDigits:d}).format(n);
const M=(n)=>new Intl.NumberFormat(loc(),{style:'currency',currency:s.compare.currency}).format(n);
const D=v=>new Intl.DateTimeFormat(loc(),{year:'numeric',month:'short',day:'numeric',timeZone:'UTC'}).format(parseDate(v));
const tiers=['classic','classicPlus','elite','elitePlus'],names={classic:'Classic',classicPlus:'Classic Plus',elite:'Elite',elitePlus:'Elite Plus'};
const enRegions=['Türkiye','Europe 1','Europe 2','Central Asia','Middle East','North Africa','Central Africa','Southern Africa','Far East','North America','South America','Oceania'];
const regionName=r=>s.lang==='en'?enRegions[data.awards.regions.indexOf(r)]:r.label;
const paths={explore:'<circle cx="12" cy="12" r="9"/><path d="m16 8-3 5-5 3 3-5Z"/>',compare:'<path d="M4 7h16m-4-4 4 4-4 4M20 17H4m4-4-4 4 4 4"/>',earn:'<path d="m3 16 7-2 6-10c1-2 4-1 3 1l-4 9 6 3v2l-8-1-5 4-1-1 2-4-6 1Z"/>',status:'<path d="m12 3 3 6 6 1-4.5 4.5 1 6-5.5-3-5.5 3 1-6L3 10l6-1Z"/>',goal:'<circle cx="12" cy="12" r="9"/><circle cx="12" cy="12" r="5"/><circle cx="12" cy="12" r="1"/>',info:'<circle cx="12" cy="12" r="9"/><path d="M12 11v6m0-10v1"/>',search:'<circle cx="10" cy="10" r="6"/><path d="m15 15 5 5"/>',check:'<path d="m5 12 4 4 10-10"/>'};
const I=k=>`<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${paths[k]||paths.info}</svg>`;
const opt=(v,l,current)=>`<option value="${esc(v)}" ${String(v)===String(current)?'selected':''}>${esc(l)}</option>`;
const sel=(id,label,opts,current)=>`<div><label for="${id}">${esc(label)}</label><select id="${id}" name="${id}">${opts.map(o=>opt(o[0],o[1],current)).join('')}</select></div>`;
const inp=(id,label,v,type='number',attrs='')=>`<div><label for="${id}">${esc(label)}</label><input id="${id}" name="${id}" type="${type}" value="${esc(v)}" ${attrs}></div>`;
const N='min="0" max="1000000000" step="1" required';
const note=text=>`<div class="notice">${I('info')}<p>${text}</p></div>`;
const row=(l,v)=>`<div class="stat-row"><span>${l}</span><strong>${v}</strong></div>`;
const prog=(p,label)=>`<div class="progress-track" role="progressbar" aria-label="${esc(label)}" aria-valuemin="0" aria-valuemax="100" aria-valuenow="${Math.round(p)}"><div class="progress-fill" style="width:${Math.max(0,Math.min(100,p))}%"></div></div>`;
const heading=(eye,title,desc)=>`<div class="page-heading"><div><p class="eyebrow">${eye}</p><h1>${title}</h1><p>${desc}</p></div><span class="source-badge">${T('Resmi THY tabloları','Official THY tables')}<br>${T('Doğrulama','Verified')}: ${D('2026-10-09')}</span></div>`;
const cabins=[['economy','Economy'],['business','Business']];
const types=()=>[['promo',W('promo')],['standard',W('standard')]];
const tierOptions=()=>tiers.map(k=>[k,names[k]]);
const awardNotice=()=>T('Tablo tutarı, ödül koltuğu veya direkt uçuş bulunduğunu göstermez. Vergi ve ücretler ayrıca ödenir; dönemsel kampanya indirimleri dahil değildir. Aktarmalı yolculuk segment segment hesaplanır; bu ekran tek segment içindir.','Table prices do not confirm award seats or direct flights. Taxes and fees are extra; temporary campaign discounts are excluded. Connections are priced segment by segment; this screen covers a single segment.');
const sample=()=>T('Örnek değerler · kendi bilgilerinizi girin.','Example figures · enter your own information.');
function toast(text){clearTimeout(timer);$('#toast').textContent=text;$('#toast').hidden=false;timer=setTimeout(()=>$('#toast').hidden=true,4000);}
function save(){try{localStorage.setItem(STORE,JSON.stringify(s));}catch{toast(T('Tarayıcı kayıt izni vermedi; bu oturumda kullanabilirsiniz.','Browser storage is unavailable; you can use this session.'));}}
function errorText(e){const a={invalid_date:['Geçerli bir tarih girin.','Enter a valid date.'],recalculate:['Uçuş bilgileri değişti. Planınıza eklemeden önce mil kazanımını yeniden hesaplayın.','Flight details changed. Recalculate earnings before adding this flight to your plan.'],invalid_period:['Dönem başlangıcı ≤ ilk yıl sonu < statü sonu olmalı.','Period start ≤ first-year end < status expiry is required.'],invalid_forecast:['Plan tarihi mevcut hesap tarihinden önce olamaz.','The plan date cannot precede the current calculation date.'],unsupported_class:['Bu rezervasyon sınıfı desteklenmiyor.','This booking class is unsupported.'],future_credit:['İşlenmiş kayıt gelecekte olamaz.','A credited record cannot be dated in the future.'],past_plan:['Planlanan kayıt geçmişte olamaz.','A planned record cannot be dated in the past.']};return a[e.message]?T(...a[e.message]):T('Geçerli sayılar girin. Mil ve uçuş sayıları negatif olmayan tam sayı olmalıdır.','Enter valid numbers. Miles and flight counts must be non-negative integers.');}
function showError(form,e){let p=form.querySelector('.error');if(!p){p=document.createElement('p');p.className='error';p.setAttribute('role','alert');form.append(p);}p.textContent=errorText(e);}
function nav(next){page=next;render();window.scrollTo({top:0,behavior:'instant'});}
function chrome(){const labels=T(['Millerimle keşfet','Mil mi, nakit mi?','Mil kazanımı','Statü planı','Yolculuk hedefim'],['Explore with miles','Miles or cash?','Earn miles','Status plan','Trip goal']);$('#navigation').innerHTML=['explore','compare','earn','status','goal'].map((k,i)=>`<button type="button" class="nav-button" data-page="${k}" ${page===k?'aria-current="page"':''}>${I(k)}${labels[i]}</button>`).join('');document.documentElement.lang=s.lang;$('#language').textContent=s.lang==='tr'?'EN':'TR';$('#language').setAttribute('aria-label',T('Switch to English','Türkçeye geç'));$('#topbar-label').textContent=T('Miles&Smiles · Kişisel mil planlayıcınız','Miles&Smiles · Your personal miles planner');$('#independent').textContent=T('Bağımsız açık kaynak proje. Türk Hava Yolları ile bağlantılı değildir.','Independent open-source project. Not affiliated with Turkish Airlines.');$('#sources-button').textContent=W('sources');$('#sources-title').textContent=W('sources');$('#close-sources').setAttribute('aria-label',W('close'));$('#github-link').textContent=T('GitHub · Açık kaynak','GitHub · Open source');}
function explore(){
 $('#view').innerHTML=heading(T('MİLLERİNİZİN SIRADAKİ DURAĞI','YOUR MILES, YOUR NEXT DESTINATION'),T('Millerimle nereye gidebilirim?','Where can my miles take me?'),T('Bakiyenize göre ödül bölgelerini keşfedin, yolculuğunuzu planlayın.','Explore award regions within your balance and plan your next trip.'))+`<section class="balance-panel"><div class="balance-side"><label for="balance">${W('balance')}</label><div class="balance-input"><input id="balance" type="number" ${N} value="${s.balance}"><span>${W('mil')}</span></div><p class="hint">${s.example?sample():T('Bakiyenizi Miles&Smiles hesabınızdan girin.','Enter the balance from your Miles&Smiles account.')}</p></div><div class="balance-config"><div class="form-grid">${sel('cabin',W('cabin'),cabins,s.cabin)}${sel('awardType',W('type'),types(),s.awardType)}</div><div class="scope-note">${I('info')}${T('Türkiye çıkışlı · Tek yön · Bir yetişkin/çocuk · Tek uçuş segmenti','From Türkiye · One way · One adult/child · One segment')}</div></div></section><div class="toolbar"><div><h2>${T('Bir sonraki yolculuğunuz','Your next journey')}</h2><p>12 ${T('ödül bölgesi · Kişi başına mil tutarı','award regions · Miles per person')}</p></div><div class="toolbar-controls"><div class="search-wrap">${I('search')}<input id="search" type="search" value="${esc(s.search)}" placeholder="${T('Bölge veya ülke ara','Search region or country')}" aria-label="${T('Bölge veya ülke ara','Search region or country')}"></div><label class="checkbox-label"><input id="affordable" type="checkbox" ${s.affordable?'checked':''}>${T('Bakiyem yeterli olanlar','Within my balance')}</label></div></div><section id="regions" class="region-grid" aria-label="${T('Ödül bölgeleri','Award regions')}"></section>`+note(awardNotice()+` <a href="${data.awards.sourceUrl}" target="_blank" rel="noopener noreferrer">${T('THY’de kontrol et','Check on THY')}</a>`);cards();
}
function cards(){const q=s.search.toLocaleLowerCase('tr-TR');const regions=data.awards.regions.filter(r=>(!s.affordable||awardCost(r,{cabin:s.cabin,type:s.awardType})<=s.balance)&&`${r.label} ${regionName(r)} ${r.countries.join(' ')}`.toLocaleLowerCase('tr-TR').includes(q));$('#regions').innerHTML=regions.map(r=>{const cost=awardCost(r,{cabin:s.cabin,type:s.awardType}),enough=cost<=s.balance;return `<article class="region-card"><div class="region-index">${T('BÖLGE','REGION')} ${String(data.awards.regions.indexOf(r)+1).padStart(2,'0')}</div><h3>${esc(regionName(r))}</h3><p class="country-preview">${r.countries.slice(0,3).map(esc).join(' · ')}${r.countries.length>3?'…':''}</p><div class="award-number">${F(cost)}<span>${W('mil')}</span></div><div class="ticket-meta">${T('Tek yön / kişi','One way / person')} · ${s.cabin==='business'?'Business':'Economy'}</div><div class="card-rule"></div><div class="affordability ${enough?'good':'low'}">${I(enough?'check':'info')}${enough?T('Bakiyeniz yeterli','Your balance covers this'):F(cost-s.balance)+' '+T('mil eksik','miles short')}</div><div class="card-actions"><button class="secondary-button" type="button" data-compare="${r.id}">${W('compare')}</button><button class="icon-button" type="button" data-goal="${r.id}" aria-label="${W('target')}: ${esc(regionName(r))}">${I('goal')}</button></div><details class="countries"><summary>${T('Bölgedeki ülkeler','Countries (official names)')} (${r.countries.length})</summary><p>${r.countries.map(esc).join(' · ')}</p></details></article>`;}).join('')||`<div class="empty-state"><h3>${T('Bu filtrelere uygun bölge yok.','No regions match these filters.')}</h3><p>${T('Bakiyenizi veya filtreleri değiştirebilirsiniz.','Try changing your balance or filters.')}</p></div>`;}
function compare(){const c=s.compare,r=compareMiles(c);$('#view').innerHTML=heading(T('MİLLERİNİZİN KARŞILIĞI','WHAT YOUR MILES SAVE'),T('Bu yolculukta mil mi, nakit mi?','Miles or cash for this trip?'),T('Aynı yolcu sayısı, kabin ve yolculuk için iki seçeneği karşılaştırın.','Compare the same passengers, cabin and journey.'))+`<div class="two-columns"><section class="panel"><h2>${T('Bilet seçenekleri','Ticket options')}</h2>${c.example?`<p class="hint">${sample()}</p>`:''}<form id="compare-form" class="form-stack">${sel('currency',T('Para birimi','Currency'),[['TRY','TRY · ₺'],['EUR','EUR · €'],['USD','USD · $'],['GBP','GBP · £']],c.currency)}${inp('cashPrice',T('Nakit biletin toplam fiyatı','Total cash ticket price'),c.cashPrice,'number','min="0.01" max="1000000000" step="0.01" required')}${inp('awardCash',T('Ödül bilet için nakit ödeme','Cash payment for the award'),c.awardCash,'number','min="0" max="1000000000" step="0.01" required')}<span class="hint">${T('Vergi, harç ve diğer nakit ücretlerin toplamı.','Include all taxes, surcharges and cash fees.')}</span>${inp('usedMiles',T('Kullanılacak toplam mil','Total miles required'),c.miles,'number','min="1" max="1000000000" step="1" required')}<button class="primary-button" type="submit">${T('Karşılaştırmayı hesapla','Calculate comparison')}</button></form></section><section><div class="result-panel" aria-live="polite"><div class="result-label">${T('Bu kullanımda mil başına tasarruf','Cash saved per mile on this offer')}</div><div class="result-hero">${F(r.valuePerMile,2)} <small>${c.currency} / ${W('mil')}</small></div><p class="hint">${T('Farklı teklifleri aynı yöntemle karşılaştırabilirsiniz.','Compare different offers using the same method.')}</p><div class="result-divider"></div>${row(T('Nakit bilet','Cash ticket'),M(r.cashPrice))}${row(T('Ödül bilet nakit ödemesi','Award cash payment'),M(r.awardCash))}${row(T('Harcanan mil','Miles spent'),F(r.miles))}${row(T('Kaçınılan nakit ödeme','Cash spending avoided'),M(r.savings))}${row(T('Nakit ödeme farkı','Cash payment difference'),F(r.percentSavings,1)+'%')}<div class="formula-box">${T('(Nakit fiyat − ödül bilet nakit ödemesi) ÷ kullanılan mil','(Cash price − award cash payment) ÷ miles used')}</div></div><div class="result-bottom"><strong>${r.savings>0?T('Bu seçenek nakit harcamanızı azaltıyor.','This option reduces your cash spending.'):T('Ödül biletin nakit ödemesi, nakit bilet fiyatına eşit veya daha yüksek.','The award cash payment equals or exceeds the cash ticket price.')}</strong><p>${T('Bagaj, değişiklik koşulları ve nakit biletin kazandıracağı milleri de değerlendirin.','Also consider baggage, change conditions and the miles a cash ticket would earn.')}</p></div></section></div>`;}
function earn(){const a=s.earn,r=calculateEarn(data.earning,a);earned=r;earnDirty=false;const inactive=a.routeType==='domestic'||['award','charter'].includes(a.ticketType);$('#view').innerHTML=heading(T('HER UÇUŞ İÇİN AYRI HESAP','CALCULATE EACH FLIGHT SEGMENT'),T('Bu uçuş bana kaç mil kazandırır?','How many miles will this flight earn?'),T('THY’nin gerçekleştirdiği uçuşlarda rezervasyon sınıfınıza göre tahmini kazanım.','Estimate earnings by booking class for THY-operated flights.'))+`<div class="two-columns"><section class="panel"><h2>${T('Uçuş bilgileri','Flight details')}</h2>${a.example?`<p class="hint">${T('Resmi örnek: Elite · IST–LAX · K sınıfı · 6.855 TPM','Official example: Elite · IST–LAX · K class · 6,855 TPM')}</p>`:''}<form id="earn-form" class="form-stack"><div class="form-grid">${sel('bookingClass',T('Rezervasyon sınıfı','Booking class'),data.earning.rules.flatMap(r=>r.bookingClasses).sort().map(c=>[c,c]),a.bookingClass)}${sel('earnTier',T('Uçuş sırasındaki statüm','My tier at time of flight'),tierOptions(),a.tier)}</div><span class="hint">${T('Biletteki tek harfli kod. EcoFly/ExtraFly veya kabin adı tek başına yeterli değildir.','Use the single-letter code on the ticket. A fare brand or cabin alone is insufficient.')}</span><div class="form-grid">${sel('routeType',T('Uçuş türü','Flight type'),[['domestic',T('İç hat','Domestic')],['international',T('Dış hat','International')]],a.routeType)}${sel('ticketType',T('Bilet türü','Ticket type'),[['paid',T('Ücretli bilet','Paid ticket')],['cashMiles','Cash&Miles'],['award',W('standard')],['charter',T('Charter uçuş','Charter flight')]],a.ticketType)}</div><div id="distance-field" ${inactive?'hidden':''}>${inp('distance',T('IATA TPM mesafesi (mil)','IATA TPM distance (miles)'),a.distance,'number',`min="1" max="20000" step="0.01" ${inactive?'disabled':'required'}`)}<span class="hint">${T('THY’nin hesaplama mesafesini girin; kilometre veya harita mesafesi kullanmayın.','Enter the official THY calculation distance, not kilometres or map distance.')}</span></div><button class="primary-button" type="submit">${T('Mil kazanımını hesapla','Calculate miles earned')}</button><p id="earn-dirty" class="error" role="status" hidden>${T('Bilgiler değişti. Güncel sonucu görmek ve uçuş eklemek için yeniden hesaplayın.','Details changed. Recalculate to see the updated result and add this flight.')}</p></form><p class="source-link"><a href="${data.earning.sourceUrl}" target="_blank" rel="noopener noreferrer">${T('Resmi kazanım tablosu','Official earning table')}</a></p></section><section><div class="result-panel" aria-live="polite"><div class="result-label">${T('Tahmini uçuş kazanımı','Estimated flight earnings')}</div><div class="result-hero">${F(r.miles)} <small>${W('mil')}</small></div><div class="result-divider"></div>${row(W('status'),F(r.miles))}${row(T('Uçuşun harcanabilir mil kazanımı','Redeemable flight earnings'),F(r.miles))}${r.fixed?row(T('İç hat sabit kazanım','Fixed domestic earnings'),F(r.miles)):row(T('Kazanım oranı','Earning rate'),F(r.rate*100)+'%')+row(T('Segment başına minimum','Minimum per segment'),F(r.minimumMiles))}<div class="formula-box">${r.fixed?T('İç hat için sabit tutar uygulanır.','A fixed domestic amount applies.'):r.miles===0?T('Ödül ve charter uçuşlar mil kazandırmaz.','Award and charter flights do not earn miles.'):`max(${F(r.distance)} × ${F(r.rate,2)}, ${F(r.minimumMiles)})`}</div><p class="hint">${T('Aynı uçuş kazanımı iki sayaçta yer alabilir; tutarlar toplanmaz. Kampanya ve hesaba özel bonuslar dahil değildir.','The same flight earning can appear in both counters; do not add the amounts. Promotions and account-specific bonuses are excluded.')}</p>${r.rawMiles!==r.miles?`<p class="hint">${T('Kesirli sonuç aşağı yuvarlanarak tahmin gösterilir; THY’nin hesaba işlediği tutar esas alınır.','Fractional results are rounded down as an estimate; the THY account credit is authoritative.')}</p>`:''}</div>${r.miles>0?`<section class="panel section-gap"><h2>${T('Bu uçuşu statü planıma ekle','Add this flight to my status plan')}</h2><form id="planned-form" class="form-stack">${inp('flightLabel',T('Uçuş / kayıt adı','Flight / record name'),'','text',`maxlength="80" required placeholder="${T('Örn. IST–LAX, TK9','E.g. IST–LAX, TK9')}"`)}${inp('flightDate',T('Uçuş tarihi','Flight date'),addDays(today(),30),'date',`min="${today()}" required`)}<p class="hint">${T('Uçuş sayısı planlama tahminidir; hesabınıza işlenen uygun uçuş sayısını daha sonra doğrulayın.','The flight count is a planning estimate; verify the eligible count once credited.')}</p><button class="primary-button" type="submit">${T('Planlanan uçuş ekle','Add planned flight')}</button></form></section>`:''}</section></div>`+note(T('Bu hesap THY tarafından gerçekleştirilen uçuşlar içindir. Ortak uçuşlarda uçuşu işleten havayolunun kuralı uygulanır.','This calculator covers THY-operated flights. Codeshares use the operating airline’s rules.'));}
function milestone(title,p,forecast=false){return `<section class="milestone"><div class="top-label"><h3>${title}</h3>${p.achieved?`<span class="status-pill">${T('Eşik sağlandı','Threshold met')}</span>`:''}</div>${row(T('Mil eşiği','Miles threshold'),F(p.totals.miles)+' / '+F(p.requirement.miles))}${prog(p.percent,title)}<p class="hint">${p.achieved?forecast?T('Plan tamamlanırsa eşik sağlanıyor.','The threshold would be met if the plan is completed.'):T('Bu hesapta gereken eşik sağlanıyor.','The required threshold is met in this calculation.'):F(p.remainingMiles)+' '+W('status')+' '+T('eksik','needed')}${p.remainingFlights!==null&&!p.achieved?' · '+T('veya uygun uçuş','or eligible flights')+': '+F(p.remainingFlights):''}</p>${p.deadline?`<p class="hint">${T('Son gün','Deadline')}: ${D(p.deadline)}${p.closed?' · '+T('Dönem tamamlandı','Period ended'):''}</p>`:''}</section>`;}
function recordsHtml(){return !s.records.length?`<p class="muted">${T('Henüz kayıt eklemediniz.','No records yet.')}</p><p class="hint">${T('Hesabınıza işlenmiş statü millerini girin veya mil kazanımı ekranından uçuş planlayın.','Enter credited Status Miles or plan a flight from the earning calculator.')}</p>`:`<div class="table-wrap"><table><thead><tr><th>${W('record')}</th><th>${W('date')}</th><th>${W('status')}</th><th>${T('Uygun uçuş','Eligible flights')}</th><th>${T('Durum','State')}</th><th></th></tr></thead><tbody>${[...s.records].sort((a,b)=>b.date.localeCompare(a.date)).map(r=>`<tr><td>${esc(r.label)}</td><td>${D(r.date)}</td><td>${F(r.statusMiles)}</td><td>${F(r.flights)}</td><td><span class="status-pill ${r.state==='planned'?'planned':''}">${W(r.state)}</span></td><td><button class="delete-button" data-delete="${esc(r.id)}" type="button" aria-label="${W('delete')}: ${esc(r.label)}">${W('delete')}</button></td></tr>`).join('')}</tbody></table></div>`;}
function status(){const a=s.status;const current=rollingTotals(s.records,a.asOf),projected=rollingTotals(s.records,a.forecast,true),expires=expiringRecords(s.records,a.asOf,a.forecast);const higher=tiers.slice(tiers.indexOf(a.tier)+1);if(higher.length&&!higher.includes(a.target))a.target=higher[0];let upgrade=higher.length?`<h2 class="section-gap">${T('Statü yükseltme','Status upgrade')} · ${names[a.target]}</h2><div class="milestone-grid">${milestone(T('İşlenmiş kayıtlar','Credited records'),promotionProgress(data.status,s.records,{target:a.target,asOf:a.asOf}))}${milestone(T('Plan dahil','Including plan')+' · '+D(a.forecast),promotionProgress(data.status,s.records,{target:a.target,asOf:a.forecast,forecast:true}),true)}</div>`:note(T('Elite Plus en üst statüdür; koruma planını aşağıdan takip edin.','Elite Plus is the highest tier; track renewal below.'));
 let renewal=a.tier==='classic'?note(T('Classic statüsü süresizdir. Yükseltme planınızı kullanabilirsiniz.','Classic is valid for life. Use your upgrade plan.')):`<section class="panel section-gap"><h2>${T('Statü koruma','Status renewal')}</h2><p class="hint">${T('Bu üç tarihi Miles&Smiles hesabınızdaki dönemlerden girin.','Enter these three period dates from your Miles&Smiles account.')}</p><form id="period-form"><div class="form-grid three">${inp('periodStart',T('Mevcut statü döneminin başlangıcı','Current status period starts'),a.start,'date','required')}${inp('firstEnd',T('İlk yılın son günü','Last day of the first year'),a.firstEnd,'date','required')}${inp('periodEnd',T('Mevcut statünün son günü','Last day of current status'),a.end,'date','required')}</div><div class="entry-actions"><button class="secondary-button" type="submit">${T('Koruma planını hesapla','Calculate renewal')}</button></div></form></section>`;
 if(a.tier!=='classic'&&a.start&&a.firstEnd&&a.end){try{const args={tier:a.tier,residence:a.residence,start:a.start,firstEnd:a.firstEnd,end:a.end};const r=renewalProgress(data.status,s.records,{...args,asOf:a.asOf});renewal+=`<div class="milestone-grid">${milestone(T('İlk yıl koşulu','First-year condition'),r.first)}${milestone(T('Tüm iki yıl koşulu','Entire two-year condition'),r.second)}</div>`+note(r.expired?T('Bu statü dönemi sona ermiş. Güncel döneminizi hesabınızdan kontrol edin.','This status period has ended. Check your current period in your account.'):r.achieved?T('Koruma eşiği bu hesapta sağlanıyor.','The renewal threshold is met in this calculation.'):T('İlk yıl veya tüm iki yıl koşullarından birinin sağlanması gerekir.','Meet either the first-year or entire two-year condition.'));if(a.forecast>a.asOf){const f=renewalProgress(data.status,s.records,{...args,asOf:a.forecast,forecast:true});renewal+=`<details class="countries"><summary>${T('Plan dahil koruma hesabı','Renewal including plan')} · ${D(a.forecast)}</summary><div class="milestone-grid">${milestone(T('İlk yıl koşulu','First-year condition'),f.first,true)}${milestone(T('Tüm iki yıl koşulu','Entire two-year condition'),f.second,true)}</div></details>`;}}catch(e){renewal+=`<p class="error section-gap">${errorText(e)}</p>`;}}
 $('#view').innerHTML=heading(T('BİR SONRAKİ STATÜNÜZ','YOUR NEXT MEMBERSHIP TIER'),T('Statü hedefiniz nerede?','How close is your status goal?'),T('İşlenmiş statü millerini ve planlanan uçuşları tarihleriyle takip edin.','Track credited Status Miles and planned flights by date.'))+`<section class="panel settings-panel"><form id="status-form"><div class="form-grid three">${sel('currentTier',T('Mevcut statüm','My current tier'),tierOptions(),a.tier)}${sel('residence',T('Yaşadığım yer','Where I live'),[['Turkey',T('Türkiye','Türkiye')],['abroad',T('Yurt dışı','Abroad')]],a.residence)}${higher.length?sel('targetTier',T('Hedef statü','Target tier'),higher.map(k=>[k,names[k]]),a.target):''}${inp('asOf',T('Mevcut hesabın tarihi','Current calculation date'),a.asOf,'date',`max="${today()}" required`)}${inp('forecast',T('Planı değerlendirme tarihi','Plan evaluation date'),a.forecast,'date',`min="${a.asOf}" required`)}</div><div class="entry-actions"><button class="primary-button" type="submit">${T('Planı güncelle','Update plan')}</button></div></form></section><div class="metric-grid"><div class="metric"><small>${T('Son 12 ayda işlenmiş','Credited in last 12 months')}</small><strong>${F(current.miles)}</strong><div class="hint">${T('Yükseltme için kayan 12 ay','Rolling 12-month upgrade window')}</div></div><div class="metric"><small>${T('Hesapta doğrulanmış uygun uçuş','Confirmed eligible flights')}</small><strong>${F(current.flights)}</strong><div class="hint">${T('İşlenmiş kayıtlar','Credited records')}</div></div><div class="metric"><small>${T('Plan tarihinde tahmini statü mili','Estimated Status Miles at plan date')}</small><strong>${F(projected.miles)}</strong><div class="hint">${T('Eski kayıtların düşmesi hesaba katılır.','Includes older records falling out.')}</div></div></div>${upgrade}${renewal}<section class="panel section-gap"><h2>${T('Kayan 12 aydan çıkacak miller','Miles leaving the rolling window')}</h2><p class="hint">${T('Bunlar harcanabilir milin son kullanım tarihleri değildir; yükseltme sayacından çıkacak kayıtlardır.','These leave the upgrade counter; they are not expiration dates of redeemable miles.')}</p>${expires.length?`<ul class="timeline-list">${expires.map(r=>`<li><div><strong>${esc(r.label)}</strong><br><span>${T('Sayaçtan çıkış','Leaves counter')}: ${D(r.expiryDate)}</span></div><strong>−${F(r.statusMiles)}</strong></li>`).join('')}</ul>`:`<p class="muted">${T('Plan tarihine kadar düşecek kayıt yok.','No records fall out before the plan date.')}</p>`}</section><section class="panel section-gap"><h2>${T('Uçuş ve statü kayıtlarım','My flights and status records')}</h2>${recordsHtml()}<details class="entry-form"><summary>${T('Manuel kayıt ekle','Add manual record')}</summary><form id="record-form" class="form-stack section-gap"><div class="form-grid">${inp('entryName',T('Kayıt adı','Record name'),'','text','maxlength="80" required')}${inp('entryDate',T('Uçuş / işlem tarihi','Flight / activity date'),today(),'date','required')}${inp('entryMiles',T('Statü mili tutarı','Status Miles amount'),'','number',N)}${inp('eligibleFlights',T('Hesapta doğrulanmış uygun uçuş sayısı','Confirmed eligible flight count'),0,'number','min="0" max="1000" step="1" required')}${sel('entryState',T('Kayıt durumu','Record state'),[['credited',W('credited')],['planned',W('planned')]],'credited')}</div><p class="hint">${T('Normal kart/bonus millerini statü mili olarak eklemeyin. Uçuş sayılmayan statü işlemi için uçuş sayısını 0 girin. Hesabınızda görünen uygun uçuş sayısını kullanın.','Do not enter ordinary card or bonus miles as Status Miles. Use 0 flights for non-flight status activities and use the eligible count confirmed by your account.')}</p><button class="primary-button" type="submit">${T('Kaydı ekle','Add record')}</button></form></details></section>`+note(T('Bu planlama hesabı üyelik statünüzü değiştirmez. Koruma ilk yıl toplamı veya tüm iki yıl toplamıyla hesaplanır. Kayan 12 ayda başlangıç günü hariç, hesap günü dahil alınır; sınır günü ve geriye dönük işlemleri THY hesabınızdaki toplamla doğrulayın.','This planning calculation does not change membership status. Renewal uses the first-year or entire two-year total. The rolling window excludes the start day and includes the calculation day; confirm boundary dates and retroactive credits with THY.'));
}
function goal(){const g=s.goal,r=data.awards.regions.find(r=>r.id===g.region),required=awardCost(r,g),p=targetProgress(s.balance,required);$('#view').innerHTML=heading(T('YOLCULUĞUNUZA KALAN MİLLER','MILES LEFT UNTIL YOUR TRIP'),T('Bir sonraki yolculuğumu planla','Plan my next trip'),T('Yolcu sayısı ve kabine göre hedefinizin mil ihtiyacını hesaplayın.','Calculate your goal by passenger count and cabin.'))+`<div class="two-columns"><section class="panel"><h2>${T('Yolculuk hedefi','Trip goal')}</h2><form id="goal-form" class="form-stack">${sel('goalRegion',T('Varış ödül bölgesi','Destination award region'),data.awards.regions.map(r=>[r.id,regionName(r)]),g.region)}<div class="form-grid">${sel('goalCabin',W('cabin'),cabins,g.cabin)}${sel('goalType',W('type'),types(),g.type)}</div><div class="form-grid">${inp('passengers',T('Yetişkin / çocuk sayısı','Adults / children'),g.passengers,'number','min="1" max="9" step="1" required')}${sel('directions',T('Yolculuk','Journey'),[['1',T('Tek yön','One way')],['2',T('Gidiş–dönüş','Round trip')]],g.directions)}</div>${inp('goalBalance',W('balance'),s.balance,'number',N)}<button class="primary-button" type="submit">${T('Hedefi güncelle','Update goal')}</button></form></section><section><div class="result-panel"><p class="eyebrow" style="color:#ffbdc7">${g.directions===2?T('Gidiş–dönüş','Round trip'):T('Tek yön','One way')} · ${g.passengers} ${T('yolcu','passengers')}</p><div class="target-name">Türkiye / ${esc(regionName(r))}</div><div class="result-hero">${F(required)} <small>${W('mil')}</small></div><p class="hint">${T('Hedef için toplam gereken','Total miles required')} · ${g.cabin==='business'?'Business':'Economy'}</p><div class="result-divider"></div>${row(T('Mevcut harcanabilir mil','Current redeemable miles'),F(s.balance))}${row(T('Biriktirilecek ek mil','Additional miles to save'),F(p.remaining))}${prog(p.percent,T('Yolculuk hedefi','Trip goal'))}<p class="hint">${p.remaining===0?T('Mil hedefiniz tamamlandı.','Your miles goal is complete.'):F(p.percent,1)+'%'}</p></div><div class="result-bottom"><p>${T('Gidiş–dönüş, aynı ödül türüyle iki tek segment varsayılır. Bebek ve aktarmalı yolculuk fiyatlandırması kapsam dışıdır.','Round trip assumes two single segments with the same award type. Infants and connecting journeys are excluded.')}</p></div><button class="text-button section-gap" type="button" data-page="explore">${T('Diğer bölgeleri keşfet','Explore other regions')}</button></section></div>`+note(awardNotice());}
function render(){chrome();({explore,compare,earn,status,goal}[page]||explore)();}
function addRecord({label,date,statusMiles,flights,state}){parseDate(date);number(statusMiles,{integer:true});number(flights,{integer:true,max:1000});if(!label.trim()||label.length>80)throw Error('input');if(state==='credited'&&date>today())throw Error('future_credit');if(state==='planned'&&date<today())throw Error('past_plan');if(!['credited','planned'].includes(state))throw Error('input');s.records.push({id:crypto.randomUUID(),label:label.trim(),date,statusMiles:Number(statusMiles),flights:Number(flights),state});save();}
const read=f=>Object.fromEntries(new FormData(f));
document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;if(b.dataset.page)nav(b.dataset.page);if(b.dataset.compare){const r=data.awards.regions.find(r=>r.id===b.dataset.compare);s.compare.miles=awardCost(r,{cabin:s.cabin,type:s.awardType});s.compare.example=true;save();nav('compare');}if(b.dataset.goal){s.goal={...s.goal,region:b.dataset.goal,cabin:s.cabin,type:s.awardType};save();nav('goal');}if(b.dataset.delete){s.records=s.records.filter(r=>r.id!==b.dataset.delete);save();status();toast(T('Kayıt silindi.','Record deleted.'));}});
function markEarnDirty(target){if(target.closest('#earn-form')){earnDirty=true;const hint=$('#earn-dirty');if(hint)hint.hidden=false;const button=$('#planned-form button[type=submit]');if(button)button.disabled=true;}}
document.addEventListener('input',e=>{markEarnDirty(e.target);if(e.target.id==='search'){s.search=e.target.value;cards();}if(e.target.id==='balance'){try{s.balance=number(e.target.value,{integer:true});s.example=false;save();cards();$('.balance-side .hint').textContent=T('Bakiyenizi Miles&Smiles hesabınızdan girin.','Enter your Miles&Smiles balance.');}catch{}}});
document.addEventListener('change',e=>{markEarnDirty(e.target);if(e.target.id==='cabin'){s.cabin=e.target.value;save();cards();}if(e.target.id==='awardType'){s.awardType=e.target.value;save();cards();}if(e.target.id==='affordable'){s.affordable=e.target.checked;save();cards();}if(['routeType','ticketType'].includes(e.target.id)){const off=$('#routeType').value==='domestic'||['award','charter'].includes($('#ticketType').value);$('#distance-field').hidden=off;$('#distance').disabled=off;$('#distance').required=!off;}if(e.target.id==='currentTier'){const form=$('#status-form'),f=read(form);try{if(!form.reportValidity())return;parseDate(f.asOf);parseDate(f.forecast);if(f.forecast<f.asOf)throw Error('invalid_forecast');s.status={...s.status,tier:f.currentTier,residence:f.residence,asOf:f.asOf,forecast:f.forecast};save();status();}catch(err){showError(form,err);}}});
document.addEventListener('submit',e=>{e.preventDefault();const form=e.target,f=read(form);try{
 if(form.id==='compare-form'){const c={cashPrice:number(f.cashPrice,{min:.01}),awardCash:number(f.awardCash),miles:number(f.usedMiles,{min:1,integer:true}),currency:f.currency,example:false};compareMiles(c);s.compare=c;save();compare();}
 if(form.id==='earn-form'){const a={bookingClass:f.bookingClass,tier:f.earnTier,routeType:f.routeType,ticketType:f.ticketType,distance:f.distance||s.earn.distance,example:false};calculateEarn(data.earning,a);s.earn=a;save();earn();}
 if(form.id==='planned-form'){if(earnDirty)throw Error('recalculate');const current=read($('#earn-form'));const confirmed=calculateEarn(data.earning,{bookingClass:current.bookingClass,tier:current.earnTier,routeType:current.routeType,ticketType:current.ticketType,distance:current.distance||s.earn.distance});if(!confirmed.miles||confirmed.miles!==earned.miles)throw Error('recalculate');addRecord({label:f.flightLabel,date:f.flightDate,statusMiles:confirmed.miles,flights:confirmed.eligibleFlights,state:'planned'});nav('status');toast(T('Planlanan uçuş eklendi.','Planned flight added.'));}
 if(form.id==='status-form'){parseDate(f.asOf);parseDate(f.forecast);if(f.forecast<f.asOf)throw Error('invalid_forecast');s.status={...s.status,tier:f.currentTier,residence:f.residence,target:f.targetTier||s.status.target,asOf:f.asOf,forecast:f.forecast};save();status();}
 if(form.id==='period-form'){renewalProgress(data.status,s.records,{tier:s.status.tier,residence:s.status.residence,start:f.periodStart,firstEnd:f.firstEnd,end:f.periodEnd,asOf:s.status.asOf});s.status={...s.status,start:f.periodStart,firstEnd:f.firstEnd,end:f.periodEnd};save();status();}
 if(form.id==='record-form'){addRecord({label:f.entryName,date:f.entryDate,statusMiles:number(f.entryMiles,{integer:true}),flights:number(f.eligibleFlights,{integer:true,max:1000}),state:f.entryState});status();toast(T('Kayıt eklendi.','Record added.'));}
 if(form.id==='goal-form'){const g={region:f.goalRegion,cabin:f.goalCabin,type:f.goalType,passengers:number(f.passengers,{min:1,max:9,integer:true}),directions:number(f.directions,{min:1,max:2,integer:true})};awardCost(data.awards.regions.find(r=>r.id===g.region),g);s.goal=g;s.balance=number(f.goalBalance,{integer:true});s.example=false;save();goal();toast(T('Yolculuk hedefi kaydedildi.','Trip goal saved.'));}
 }catch(err){showError(form,err);}});
$('#language').addEventListener('click',()=>{s.lang=s.lang==='tr'?'en':'tr';save();render();});
$('#sources-button').addEventListener('click',()=>{$('#sources-content').innerHTML=`<p>${T('Tutarlar aşağıdaki resmi kaynaklardan kontrol edildi. THY hesabınızdan otomatik bakiye veya uçuş alınmaz.','Figures were checked against the official sources below. Your THY balance and flights are not synced automatically.')}</p><p>${T('Son doğrulama','Last verified')}: ${D('2026-10-09')}</p><ul><li><a href="${data.awards.sourceUrl}" target="_blank" rel="noopener noreferrer">${T('Ödül bilet tablosu','Award ticket table')}</a></li><li><a href="${data.earning.sourceUrl}" target="_blank" rel="noopener noreferrer">${T('Uçuş mil kazanımı','Flight earning table')}</a></li><li><a href="${data.status.sources.status.url}" target="_blank" rel="noopener noreferrer">${T('Statü kuralları','Status rules')}</a></li></ul><p>${T('Ödül keşfi THY’nin Türkiye çıkışlı tek segment tablosunu kullanır. Program ortaklarının ayrı tabloları bu sürümde yoktur.','Award exploration uses THY’s single-segment table from Türkiye. Separate partner tables are not included in this version.')}</p><p>${T('Bakiye, uçuşlar ve hedefler yalnız bu tarayıcıda saklanır.','Your balance, flights and goals are saved only in this browser.')}</p>`;$('#sources-dialog').showModal();});
$('#close-sources').addEventListener('click',()=>$('#sources-dialog').close());
$('#view').innerHTML=`<p class="loading">${T('Resmi kural tabloları yükleniyor…','Loading official rule tables…')}</p>`;
try{const entries=await Promise.all(['awards','earning','status'].map(async k=>{const r=await fetch(`./data/${k}.json`);if(!r.ok)throw Error('data');return [k,await r.json()];}));data=Object.fromEntries(entries);render();registerTools();}catch(e){console.error(e);$('#view').innerHTML=`<p class="error" role="alert">${T('Veriler yüklenemedi. Bağlantınızı kontrol edip sayfayı yeniden açın.','Data could not load. Check your connection and reload the page.')}</p>`;}
function registerTools(){if(!document.modelContext?.registerTool)return;const lifecycle=new AbortController();window.addEventListener('pagehide',()=>lifecycle.abort(),{once:true});const register=tool=>{try{Promise.resolve(document.modelContext.registerTool(tool,{signal:lifecycle.signal})).catch(()=>{});}catch{}};
 register({name:'calculate_miles_cash_comparison',title:'Compare miles and cash',description:'Configure the visible comparison using total cash price, award cash fees and miles. Does not book or access an account.',inputSchema:{type:'object',properties:{cashPrice:{type:'number',exclusiveMinimum:0},awardCash:{type:'number',minimum:0},miles:{type:'integer',minimum:1},currency:{type:'string',enum:['TRY','EUR','USD','GBP']}},required:['cashPrice','awardCash','miles','currency'],additionalProperties:false},annotations:{readOnlyHint:false,untrustedContentHint:false},execute(input){if(!input||!['TRY','EUR','USD','GBP'].includes(input.currency))throw Error('invalid_currency');const result=compareMiles(input);s.compare={...input,example:false};save();nav('compare');return result;}});
 register({name:'calculate_flight_miles',title:'Estimate THY flight miles',description:'Configure the visible THY earning calculator from booking class and IATA TPM. Does not add a flight record or access an account.',inputSchema:{type:'object',properties:{bookingClass:{type:'string'},tier:{type:'string',enum:tiers},routeType:{type:'string',enum:['domestic','international']},distance:{type:'number',minimum:1,maximum:20000},ticketType:{type:'string',enum:['paid','award','cashMiles','charter']}},required:['bookingClass','tier','routeType','ticketType'],additionalProperties:false},annotations:{readOnlyHint:false,untrustedContentHint:false},execute(input){const result=calculateEarn(data.earning,input);s.earn={...input,distance:input.distance||s.earn.distance,example:false};save();nav('earn');return result;}});
}
